<?php require 'config.php'; require 'lib.php'; need_login(true); track_user(); csrf_check();
$LV=['debug'=>0,'info'=>1,'warning'=>2,'error'=>3]; $LN=['debug'=>'Debug','info'=>'Info','warning'=>t('Varning','Warning'),'error'=>t('Fel','Error')];
$GRP=['auth'=>['auth'],'snmp'=>['snmp','network'],'tcp'=>['tcp'],'url'=>['url'],'zabbix'=>['zabbix'],'pbs'=>['pbs'],'proxmox'=>['proxmox'],'vmhv'=>['vmware','hyperv'],'worker'=>['worker'],'alerts'=>['alert','notify'],'config'=>['config','settings']];
$GN=['auth'=>t('Inloggning','Login'),'snmp'=>'SNMP','tcp'=>t('TCP-kontroller','TCP checks'),'url'=>t('URL-kontroller','URL checks'),'zabbix'=>'Zabbix agent','pbs'=>'PBS API','docker'=>'Docker','proxmox'=>'Proxmox API','vmhv'=>'VMware / Hyper-V','worker'=>t('Worker (systemd)','Worker (systemd)'),'alerts'=>t('Larm och notifieringar','Alerts and notifications'),'config'=>t('Konfiguration','Configuration')];
if($_SERVER['REQUEST_METHOD']==='POST'){ $a=$_POST['a']??'';
 if($a==='debug'){ set_setting('log_debug',!empty($_POST['on'])?'1':'0'); }
 if($a==='clear'){ db()->exec('DELETE FROM app_log'); applog('info','config','Log cleared'); }
 header('Location: logs.php?'.http_build_query(array_intersect_key($_GET,array_flip(['lvl','src','q','n','auto']))));exit; }
$lvl=isset($LV[$_GET['lvl']??''])?$_GET['lvl']:'info'; $src=preg_replace('/[^\w]/','',$_GET['src']??''); $q=trim($_GET['q']??''); $n=in_array((int)($_GET['n']??0),[100,250,500,1000],true)?(int)$_GET['n']:250; $auto=!empty($_GET['auto']); $pg=max(0,(int)($_GET['p']??0));
$w=[]; $p=[]; $ls=array_keys(array_filter($LV,fn($x)=>$x>=$LV[$lvl])); $w[]='level IN ('.implode(',',array_map(fn($x)=>"'$x'",$ls)).')';
if(isset($GRP[$src])){ $w[]='src IN ('.implode(',',array_map(fn($x)=>"'$x'",$GRP[$src])).')'; } if($q!==''){ $w[]='(msg LIKE ? OR usr LIKE ?)'; $p[]='%'.$q.'%'; $p[]='%'.$q.'%'; }
$st=db()->prepare('SELECT * FROM app_log WHERE '.implode(' AND ',$w).' ORDER BY id DESC LIMIT '.($n+1).' OFFSET '.($pg*$n)); try{ $st->execute($p); $rows=$st->fetchAll(); $tbl=true; }catch(Throwable $e){ $rows=[]; $tbl=false; }
$more=count($rows)>$n; $rows=array_slice($rows,0,$n);
$SN=['check'=>t('Kontroller','Checks'),'host'=>t('Virtualisering','Virtualization'),'network'=>'SNMP','snmp'=>'SNMP','tcp'=>'TCP','url'=>'URL','zabbix'=>'Zabbix agent','pbs'=>'PBS API','docker'=>'Docker','proxmox'=>'Proxmox API','vmware'=>'VMware','hyperv'=>'Hyper-V','alert'=>t('Larm','Alerts'),'notify'=>t('Notifieringar','Notifications'),'auth'=>t('Inloggning','Login'),'config'=>t('Konfiguration','Configuration'),'worker'=>'Worker','poll'=>'Poll','settings'=>t('Inställningar','Settings')];
$qs=fn($x=[])=>'logs.php?'.http_build_query(array_merge(['lvl'=>$lvl,'src'=>isset($GRP[$src])?$src:null,'q'=>$q?:null,'n'=>$n,'auto'=>$auto?1:null],$x));
top(t('Loggar','Logs')); flash(); ?>
<h2><?= t('Inställningar','Settings') ?></h2>
<?php settings_tabs('logs'); ?>
<?php if(!$tbl) echo '<p class="card badt">'.t('Tabellen app_log saknas – kör sql/migrate_v18.sql.','The app_log table is missing – run sql/migrate_v18.sql.').'</p>'; ?>
<form method="get" class="card inline"><label class="f"><?= t('Loggnivå','Log level') ?><select name="lvl"><?php foreach($LN as $k=>$nm) echo '<option value="'.$k.'"'.($k===$lvl?' selected':'').'>'.h($nm).($k==='debug'?'':($k==='error'?'':' '.t('och högre','and higher'))).'</option>'; ?></select></label>
<label class="f"><?= t('Källa','Source') ?><select name="src"><option value=""><?= t('Alla','All') ?></option><?php foreach($GN as $k=>$nm) echo '<option value="'.h($k).'"'.($k===$src?' selected':'').'>'.h($nm).'</option>'; ?></select></label>
<label class="f"><?= t('Sök','Search') ?><input name="q" value="<?= h($q) ?>" placeholder="<?= t('server, check, användare…','server, check, user…') ?>"></label>
<label class="f"><?= t('Antal rader','Rows') ?><select name="n"><?php foreach([100,250,500,1000] as $x) echo '<option'.($x===$n?' selected':'').'>'.$x.'</option>'; ?></select></label>
<label class="chk"><input type="checkbox" name="auto" value="1"<?= $auto?' checked':'' ?>> <?= t('Uppdatera automatiskt','Auto refresh') ?></label>
<button class="btn"><?= t('Visa','Show') ?></button></form>
<div class="card inline"><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="a" value="debug"><label class="chk"><input type="checkbox" name="on" value="1" onchange="this.form.submit()"<?= setting('log_debug','0')==='1'?' checked':'' ?>> <?= t('Logga även debug (varje poll-cykel – ger mycket data)','Also log debug (every poll cycle – produces a lot of data)') ?></label></form></div>
<?php if($src==='worker'): ?><div class="card"><b><?= t('systemd-journal för bakgrundstjänsten','systemd journal for the background service') ?></b> <small class="mut">(<?= h(setting('worker_unit','vmmon-worker')) ?>)</small>
<?php if(!empty($_GET['journal'])){ $j=journal_tail(setting('worker_unit','vmmon-worker'),200); echo '<pre class="jr">'.h($j[1]).'</pre>'; if(!$j[0]) echo '<p class="mut">'.t('Webbservern får inte läsa journalen. Lägg webbserver-användaren i gruppen systemd-journal (t.ex. sudo usermod -aG systemd-journal www-data) och starta om webbservern/php-fpm. Worker-händelserna ovan loggas även utan detta.','The web server may not read the journal. Add the web-server user to the systemd-journal group (e.g. sudo usermod -aG systemd-journal www-data) and restart the web server/php-fpm. Worker events below are logged without this too.').'</p>'; } else echo '<p><a class="btn sm" href="'.h($qs(['journal'=>1])).'">'.t('Visa journalen (senaste 200 rader)','Show journal (last 200 lines)').'</a></p>'; ?></div><?php endif; ?>
<div class="sc5" style="max-height:none"><table class="card"><tr><th><?= t('Tid','Time') ?></th><th><?= t('Nivå','Level') ?></th><th><?= t('Källa','Source') ?></th><th><?= t('Meddelande','Message') ?></th><th><?= t('Användare','User') ?></th></tr>
<?php foreach($rows as $r): ?><tr><td style="white-space:nowrap"><?= h($r['ts']) ?></td><td><span class="lv lv-<?= h($r['level']) ?>"><?= h($LN[$r['level']]) ?></span></td><td><?= h($SN[$r['src']]??$r['src']) ?></td><td class="det"><?= h($r['msg']) ?></td><td><?= h($r['usr']??'') ?></td></tr>
<?php endforeach; if(!$rows) echo '<tr><td colspan="5" class="mut">'.t('Inga loggrader för valda filter.','No log rows for the selected filters.').'</td></tr>'; ?></table></div>
<p class="inline"><?php if($pg>0) echo '<a class="btn sm" href="'.h($qs(['p'=>$pg-1])).'">← '.t('Nyare','Newer').'</a>'; if($more) echo '<a class="btn sm" href="'.h($qs(['p'=>$pg+1])).'">'.t('Äldre','Older').' →</a>'; ?></p>
<?php if($auto) echo '<script>setTimeout(function(){location.reload()},10000)</script>'; bottom();
